//! Consensus and finality boundary.
use std::{collections::BTreeMap,sync::Mutex};use crate::security::simple_hash;
#[derive(Clone,Debug)]pub struct Vote{pub block:[u8;32],pub voter:String,pub approve:bool,pub signature:[u8;64]}
pub struct ConsensusEngine{pub chain_id:u64,pub proposer:String,height:Mutex<u64>,votes:Mutex<BTreeMap<[u8;32],Vec<Vote>>>}impl ConsensusEngine{pub fn new(chain_id:u64,proposer:String)->Self{Self{chain_id,proposer,height:Mutex::new(0),votes:Mutex::new(BTreeMap::new())}}pub fn propose_id(&self,h:u64,parent:[u8;32],state:[u8;32],tx:[u8;32])->[u8;32]{let mut b=Vec::new();b.extend_from_slice(&self.chain_id.to_be_bytes());b.extend_from_slice(&h.to_be_bytes());b.extend_from_slice(&parent);b.extend_from_slice(&state);b.extend_from_slice(&tx);b.extend_from_slice(self.proposer.as_bytes());simple_hash(&b)}pub fn vote(&self,v:Vote){self.votes.lock().unwrap().entry(v.block).or_default().push(v)}pub fn finality(&self,id:&[u8;32],quorum:usize)->bool{self.votes.lock().unwrap().get(id).map(|v|v.iter().filter(|x|x.approve).count()>=quorum).unwrap_or(false)}pub fn set_height(&self,h:u64){*self.height.lock().unwrap()=h}}
